  const pad = {l:52,r:18,t:18,b:36};
  const pw = W-pad.l-pad.r, ph = H-pad.t-pad.b;
  const X = k => pad.l + (k/m)*pw;
  const Y = p => pad.t + (1-p)*ph;

  // 水平网格线
  ctx.font = '11px ui-sans-serif, -apple-system, sans-serif';
  ctx.textAlign='right'; ctx.textBaseline='middle';
  for(let p=0;p<=1.0001;p+=0.25){
    const y = Y(p);
    ctx.strokeStyle = p===0 ? '#3d444d' : '#1e242c';
    ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(W-pad.r, y); ctx.stroke();
    ctx.fillStyle='#7d8590';
    ctx.fillText(Math.round(p*100)+'%', pad.l-8, y);
  }

  // x 轴刻度
  const step = Math.max(1, Math.ceil(m/8));
  ctx.textAlign='center'; ctx.textBaseline='top';
