```
const $ = s => document.querySelector(s);

const LF = new Float64Array(301);
for(let i=1;i<=300;i++) LF[i]=LF[i-1]+Math.log(i);
function logC(n,r){
  if(r<0||r>n||n<0) return -Infinity;
  return LF[n]-LF[r]-LF[n-r];
}
function probAt(m,k,n,q){
  if(k<q) return 0;
  if(m-k<=n-q) return 1;
  const den = logC(m,n);
  let s=0;
  const hi=Math.min(n,k);
  for(let i=q;i<=hi;i++){
    const v=logC(k,i)+logC(m-k,n-i)-den;
    if(v>-Infinity) s+=Math.exp(v);
  }
  return Math.min(1,s);
}
```

注意：当 m-k <= n-q 时就是 1——但会不会出现 m-k < 0 的情况？不会。

小心：如果 k = m，那么 m-k = 0，而 n-q >= 0，所以 0 <= n-q 一定成立 → 返回 1。没问题。

